# NOTICE: Generated by Claude (LLM). Review before relying on it.
"""Build-up frames of the week 9 "Training Costs Since Strubell et al." chart.

Reads data.csv next to this script (sources in SOURCES.md) and writes five
SVGs beside it, all on one fixed canvas so the axes stay put from slide to slide:

    1-axes.svg       year and log cost axes only
    2-strubell.svg   + Strubell et al. 2019, Table 3 cost ranges
    3-reported.svg   + costs since 2020 the developer published (DeepSeek)
    4-estimates.svg  + outside estimates since 2020 (Epoch AI, Cottier et al.)
    5-linear.svg     everything again, on a linear cost axis

    python3 docs/assets/llms/training-cost/make_figures.py
"""
import csv
from pathlib import Path

import matplotlib

matplotlib.use("svg")
import matplotlib.pyplot as plt
from matplotlib import font_manager
from matplotlib.legend_handler import HandlerTuple
from matplotlib.lines import Line2D

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[3]

# Deck neutrals (docs/slides/theme/blue-line.scss).
INK, MUTED, BORDER = "#231f20", "#666666", "#d8d8d8"
# Each developer's dot and label share its brand color, darkened where needed to
# reach 4.5:1 text contrast on white. DeepMind counts as Google (Alphabet).
# Neighboring points pass the dataviz CVD validator except Google red vs. Hugging
# Face mustard (red-green CVD), where the label beside each dot carries identity.
# Meta and DeepSeek share a blue but never sit near each other.
BRAND = {
    "Google": "#c5221f", "DeepMind": "#c5221f", "Google DeepMind": "#c5221f",  # Google red
    "OpenAI": INK,  # black logo
    "AllenAI": "#105257",  # Ai2 dark teal
    "Microsoft / NVIDIA": "#0067b8",  # Microsoft blue
    "BigScience / Hugging Face": "#7a6500",  # Hugging Face yellow, darkened
    "Meta": "#0866ff",  # Meta blue
    "DeepSeek": "#3d5af1",  # DeepSeek blue, darkened
    "xAI": "#6b6b6b",  # black logo; gray to tell it from OpenAI
}
SIZE, AX = (11, 7.4), [0.09, 0.07, 0.89, 0.83]

font_manager.fontManager.addfont(str(ROOT / "docs/assets/fonts/mulish/Mulish-wght.ttf"))
plt.rcParams.update({
    "font.family": ["Mulish", "DejaVu Sans"],
    "font.size": 15,
    "text.color": INK,
    "text.parse_math": False,
    "svg.fonttype": "path",
})

# Log frames: cost centered just above ("a") or below ("b") the dot or range bar, and model
# name in parentheses at a spot from NAME_SPOT or an explicit (anchor, dx, dy, ha, va).
COST_GAP, NAME_GAP, LINE = 3, 7, 15  # points past a dot's edge or a bar's end; one text line
NAME_SPOT = {  # (anchor: dot "mid" or bar end "lo", dx, dy in points, ha, va)
    "r": ("mid", 9, 0, "left", "center"), "l": ("mid", -9, 0, "right", "center"),
    "b": ("lo", 0, -NAME_GAP, "center", "top"),
}
LABELS = {  # model: (cost side, name spot); cost goes below only where a neighbor is in the way
    "T2T big": ("a", "b"), "ELMo": ("a", "r"), "BERT base": ("a", "r"), "GPT-2": ("a", "r"),
    "NAS": ("a", "l"), "GPT-3": ("a", "b"),
    "Megatron-Turing NLG": ("a", ("hi", 18, COST_GAP + LINE, "right", "bottom")),  # up and left, clear of GPT-3
    "Gopher": ("b", "r"), "BLOOM": ("b", "r"), "PaLM": ("a", "r"), "GPT-4": ("b", "r"),
    "Gemini Ultra": ("a", "l"), "Llama 3.1 405B": ("a", "r"), "DeepSeek-V3": ("a", "r"),
    "DeepSeek-R1": ("a", "l"), "Grok 3": ("a", "l"),
}
LINEAR = {  # labeled points on the linear axis: model: (dx in years, ha)
    "GPT-4": (-0.12, "right"), "Gemini Ultra": (-0.12, "right"), "Llama 3.1 405B": (0.25, "center"),
    "Grok 3": (-0.12, "right"),
}
LINEAR_DY = {"Llama 3.1 405B": 0.75}  # on the linear axis, below its marker instead of above
JITTER = {"BERT base": -0.12, "ELMo": 0.12, "Llama 3.1 405B": 0.08, "DeepSeek-V3": 0.15,
          "DeepSeek-R1": -0.15, "Grok 3": 0.05, "Gopher": 0.1,
          "Megatron-Turing NLG": -0.1, "Gemini Ultra": -0.1, "GPT-4": 0.1}
LEGEND = {  # shape, not color: color is the developer
    "strubell": (Line2D([], [], marker="|", ls="", ms=18, mew=2, mec=MUTED),
                 Line2D([], [], marker="o", ls="", ms=10, mfc="white", mec=MUTED, mew=2)),
    "reported": Line2D([], [], marker="o", ls="", ms=10, mfc=MUTED, mec=MUTED),
    "estimate": Line2D([], [], marker="o", ls="", ms=10, mfc="white", mec=MUTED, mew=2),
}
LEGEND_TEXT = {"strubell": "Strubell et al. 2019 estimate (range)", "reported": "Since 2020, developer-reported",
               "estimate": "Since 2020, outside estimate"}


def load():
    rows = list(csv.DictReader(open(HERE / "data.csv", encoding="utf-8")))
    for r in rows:
        for k in ("cost_low_usd", "cost_high_usd"):
            r[k] = float(r[k]) if r[k] else None
        r["year"] = int(r["year"])
    return {r["model"]: r for r in rows}


def group(r):
    """Strubell's 2019 rows, costs the developer published, or outside estimates."""
    if r["era"] == "strubell":
        return "strubell"
    return "reported" if r["cost_basis"].startswith(("reported", "derived")) else "estimate"


def money(x):
    if x >= 1e6:
        return f"${x / 1e6:,.0f}M" if x >= 1e7 else f"${x / 1e6:,.1f}M"
    if x >= 1e3:
        return f"${x / 1e3:,.0f}k"
    return f"${x:,.0f}"


def frame(d, show, name, linear=False):
    fig = plt.figure(figsize=SIZE)
    ax = fig.add_axes(AX)  # fixed, not bbox-tight, so frames line up
    for m, (cost_side, spot) in LABELS.items():
        r = d[m]
        if group(r) not in show:
            continue
        x = r["year"] + JITTER.get(m, 0)
        lo, hi = r["cost_low_usd"], r["cost_high_usd"]
        mid = (lo * hi) ** 0.5
        c = BRAND[r["developer"]]
        if lo != hi:
            ax.plot([x, x], [lo, hi], color=c, lw=2, solid_capstyle="round", zorder=2)
        filled = group(r) == "reported"
        ax.plot(x, mid, "o", ms=10, mfc=c if filled else "white", mec=c, mew=2, zorder=3)
        if linear and hi < 5e7:
            continue  # sits on the baseline; covered by the note below
        label = r["label"].replace(" (reasoning stage only)", " (RL step)")
        cost = money(hi) if lo == hi else money(lo) + "–" + money(hi)
        if linear:
            dx, ha = LINEAR[m]
            ax.text(x + dx, mid * LINEAR_DY.get(m, 1), f"{label}  {cost}", ha=ha, va="center",
                    fontsize=12.5, color=c)
            continue
        edge = 0 if lo != hi else 5  # a lone dot's edge is ~5 pt from its center
        if cost_side == "a":
            ax.annotate(cost, (x, hi), xytext=(0, edge + COST_GAP), textcoords="offset points",
                        ha="center", va="bottom", fontsize=12.5, color=c)
        else:
            ax.annotate(cost, (x, lo), xytext=(0, -edge - COST_GAP), textcoords="offset points",
                        ha="center", va="top", fontsize=12.5, color=c)
        anchor, dx, dy, ha, va = NAME_SPOT.get(spot, spot)
        dy += {"hi": edge, "lo": -edge}.get(anchor, 0)
        ax.annotate(f"({label})", (x, {"mid": mid, "hi": hi, "lo": lo}[anchor]), xytext=(dx, dy),
                    textcoords="offset points", ha=ha, va=va, fontsize=11.5, color=c)
    if linear:
        ax.set_ylim(0, 1e9)
        ax.set_yticks([0, 2e8, 4e8, 6e8, 8e8, 1e9], ["$0", "$200M", "$400M", "$600M", "$800M", "$1B"])
        ax.text(2016.6, 1.1e8, "Everything else, 2017–2025: under $15M each", ha="left", va="bottom",
                fontsize=12.5, color=MUTED, fontstyle="italic")
    else:
        ax.set_yscale("log")
        ax.set_ylim(100, 5e9)
        ticks = [1e2, 1e3, 1e4, 1e5, 1e6, 1e7, 1e8, 1e9]
        ax.set_yticks(ticks, ["$100", "$1k", "$10k", "$100k", "$1M", "$10M", "$100M", "$1B"])
    ax.minorticks_off()
    ax.set_xlim(2016.4, 2026.0)
    ax.set_xticks(range(2017, 2026))
    ax.grid(axis="y", color=BORDER, lw=0.8)
    ax.set_axisbelow(True)
    for side in ("top", "right", "left", "bottom"):
        ax.spines[side].set_visible(side == "bottom")
    ax.spines["bottom"].set_color(BORDER)
    ax.tick_params(colors=MUTED, length=0)
    keys = [k for k in ("strubell", "reported", "estimate") if k in show]
    if keys:
        ax.legend([LEGEND[k] for k in keys], [LEGEND_TEXT[k] for k in keys], loc="upper left", frameon=False,
                  fontsize=12, labelcolor=MUTED, handler_map={tuple: HandlerTuple(ndivide=1)})
    ax.set_title("Compute cost to train one model", loc="left", fontsize=19, fontweight="bold", pad=14)
    fig.savefig(HERE / f"{name}.svg", transparent=True)
    plt.close(fig)


if __name__ == "__main__":
    data = load()
    frame(data, set(), "1-axes")
    frame(data, {"strubell"}, "2-strubell")
    frame(data, {"strubell", "reported"}, "3-reported")
    frame(data, {"strubell", "reported", "estimate"}, "4-estimates")
    frame(data, {"strubell", "reported", "estimate"}, "5-linear", linear=True)
